export const NEIGHBOUR_NAMES=['Milo','June','Nori','Tess','Remy','Poppy','Finn','Wren','Otis','Luna','Bea','Arlo','Faye','Noel','Kit','Ivy','Theo','Mina','Rory','Ada','Eli','Zoe-bell','Pax','Joy','Leo','Fern','Mae','Ollie'];
export const JOBS={read:{label:'Reading corner',answer:'I am reading a story. This book has lovely pictures.',model:'I like your book.'},water:{label:'Garden helper',answer:'I am watering the flowers. They need a little drink.',model:'The flowers are pretty.'},paint:{label:'Art corner',answer:'I am painting a colourful picture. Look at the bright colours!',model:'I like your picture.'},sweep:{label:'Path helper',answer:'I am sweeping the path. We can keep our park tidy.',model:'Thank you for helping.'},deliver:{label:'Friendly delivery',answer:'I am taking a little parcel to my friend. It is a special surprise.',model:'Here is your parcel.'},dance:{label:'Music practice',answer:'I am practising my happy dance. Would you like to dance with me?',model:'I can dance with you.'},walk:{label:'Town explorer',answer:'I am exploring our lovely town. There are so many friends to meet!',model:'Let us walk together.'}};
export const SOCIAL_LINES={hello:'Hello, friend! It is lovely to meet you.',question:'What are you doing?',help:'Can I help you?',thanks:'Yes, please! Thank you for being kind.',encourage:'Your turn. You can say hello, ask a question, or try the sentence on the screen.',close:'See you soon! Enjoy your adventure.',near:'Walk a little closer to a neighbour. Then tap Talk to a friend.',arrival:'Walk onto the yellow spot. Your story will start there. Use the hand only when you need to pick something up.',next:'Have a try out loud. When you are ready, tap Next.',food:'Choose a food from the list. Your friend will walk over, pick it up, and help you say its name.'};
export function neighbourIdentity(index,job){return {name:NEIGHBOUR_NAMES[index%NEIGHBOUR_NAMES.length],job:job||Object.keys(JOBS)[index%7]};}
// Schoolbus's nearby wave-and-greet flow: a varied short exchange in the usual caption dock.
export const GREETINGS=[{model:'Hello! How are you?',reply:'Hello! I am happy today. How are you?'},{model:'Good morning! It is nice to see you.',reply:'Good morning, friend! It is nice to see you too.'},{model:'Hello! What are you doing?',reply:'Hello! Come and have a look.'},{model:'Hi! May I play with you?',reply:'Of course! We can play together.'}];
export function neighbourAppearance(i){const senior=i%7===0,adult=!senior&&i%3===0,sport=i%4===1;return {skin:[0xffd8bb,0xd5a16e,0x8f6049,0xc58a63][i%4],hair:senior?0xd6d3ce:[0x5b4837,0x27232c,0x9b7049,0x402a23][i%4],top:[0xb9a3ce,0x80b6c3,0xe7a8b5,0xe6c477,0x9bbf84][i%5],pants:i%2===0||sport?0x43576c:0,dress:i%2===1&&!sport,age:senior?2:adult?1:0,glasses:senior||i%9===2,short:i%3===0,pony:i%6===2,bun:i%6===3,cap:sport?0xf0b16d:0,bag:i%3===1?0x769fae:0,s:senior?1.95:adult?2.05:1.6+(i%3)*.08};}
